<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?= $this->include('pages/partials/page_heading') ?><section ng-controller="adminUserController" ng-cloak><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><article class="card sitara-card"><header class="card-header d-flex justify-content-between align-items-center"><div><h2 class="sitara-card-title">Pengguna administrator</h2><p class="sitara-card-subtitle">Kelola akun yang dapat mengakses administrasi SITARA.</p></div><button class="btn btn-sm btn-primary" ng-click="open()">Tambah admin</button></header><div class="table-responsive"><table class="table sitara-table"><thead><tr><th>Nama</th><th>Username</th><th>Email</th><th>Login terakhir</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><tr ng-repeat="x in datas"><td class="table-main" ng-bind="x.full_name"></td><td ng-bind="x.username"></td><td ng-bind="x.email||'-'"></td><td ng-bind="x.last_login_at||'Belum pernah'"></td><td ng-bind="x.is_active?'Aktif':'Nonaktif'"></td><td><div class="sitara-row-actions justify-content-end"><button class="btn btn-sm btn-outline-primary" ng-click="open(x)">Ubah</button><button class="btn btn-sm btn-outline-warning" ng-click="openPassword(x)">Password</button></div></td></tr></tbody></table></div></article>
<div class="modal fade" id="adminUserModal"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form name="adminForm" ng-submit="save(adminForm)"><div class="modal-header"><h2 class="modal-title h5" ng-bind="model.id?'Ubah admin':'Tambah admin'"></h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama lengkap</label><input class="form-control" ng-model="model.full_name" required></div><div class="col-md-6"><label class="form-label">Username</label><input class="form-control" ng-model="model.username" required></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control" ng-model="model.email"></div><div class="col-md-6" ng-if="!model.id"><label class="form-label">Password awal</label><input type="password" minlength="8" class="form-control" ng-model="model.password" required></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" id="adminActive" ng-model="model.is_active"><label class="form-check-label" for="adminActive">Akun aktif</label></div></div></div></div><div class="modal-footer"><button class="btn btn-outline-gray" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan admin</button></div></form></div></div></div><div class="modal fade" id="adminPasswordModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form name="passwordForm" ng-submit="savePassword(passwordForm)"><div class="modal-header"><h2 class="modal-title h5">Ubah password</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p ng-bind="passwordModel.name"></p><label class="form-label">Password baru</label><input type="password" minlength="8" class="form-control" ng-model="passwordModel.password" required></div><div class="modal-footer"><button class="btn btn-primary">Simpan password</button></div></form></div></div></div></section><script>window.SITARA_ADMIN_USER_CONFIG=<?= json_encode(['baseUrl'=>site_url('pengaturan/admin')]) ?>;window.SITARA_CSRF=<?= json_encode(['header'=>$csrfHeader,'hash'=>$csrfHash]) ?>;</script><?= $this->endSection() ?>
